text:
TipHow to use this page




Adjust any of the model parameters using the sliders / inputs below. The headline outcomes (deaths averted, burden avoided, net monetary benefit, ROI) update live in your browser — nothing is sent to any server.
Export your scenario by clicking Download my scenario CSV. Save the file with a meaningful name (e.g. scenario_low_eta.csv).
Reload later by clicking Import a saved scenario and selecting your saved CSV — the inputs will repopulate from the file.
Reset at any time using the Reset to canonical v3 button.

The starting values are loaded from the canonical amua_import_parameters_v3.csv. For provenance and source citations on every parameter, see the Parameters Hub.
Code
csvText = FileAttachment("amua_import_parameters_v3.csv").text()

canonical = {
  const lines = csvText.split("\n").filter(l =&gt; l && !l.startsWith("#") && !l.startsWith("Name,"));
  const out = {};
  for (const line of lines) {
    const m = line.match(/^([^,]+),([^,]+),(.*)$/);
    if (!m) continue;
    const [, name, expr, notes] = m;
    const v = parseFloat(expr);
    if (!isNaN(v)) out[name.trim()] = { value: v, notes };
  }
  return out;
}
Code
mutable importedScenario = null

viewof importFile = Inputs.file({
  label: "Import a saved scenario",
  accept: ".csv",
  multiple: false
})
Code
handleImport = {
  if (importFile) {
    const text = await importFile.text();
    const lines = text.split("\n").filter(l =&gt; l && !l.startsWith("#") && !l.startsWith("Name,"));
    const obj = {};
    for (const line of lines) {
      const m = line.match(/^([^,]+),([^,]+),(.*)$/);
      if (!m) continue;
      const v = parseFloat(m[2]);
      if (!isNaN(v)) obj[m[1].trim()] = v;
    }
    mutable importedScenario = obj;
    return html`&lt;div class="alert alert-success" style="padding:8px;background:#cfc;border-left:4px solid #060;margin:8px 0;"&gt;
      ✓ Imported ${Object.keys(obj).length} parameters. Adjust below or export again.
    &lt;/div&gt;`;
  }
  return html``;
}

Editable parameters


Code
// Helper: starting value picks (a) imported scenario, (b) canonical v3
function start(name) {
  if (importedScenario && importedScenario[name] !== undefined) return importedScenario[name];
  return canonical[name]?.value ?? 0;
}








Burden


Code
viewof n_deaths_statssa_macod = Inputs.range([1000, 4000], {
  step: 50,
  value: start("n_deaths_statssa_macod"),
  label: "Annual deaths (StatsSA MACOD) — n_deaths_statssa_macod ← canonical truth"
})
viewof cfr_headline_mid = Inputs.range([0.05, 0.20], {
