deltaTable = Inputs.table(
  editedKeys.map(([k, v]) =&gt; {
    const base = canonical[k]?.value;
    const delta = base ? ((v - base) / base * 100) : 0;
    return {
      Parameter: k,
      "Canonical (v3)": base,
      "Your value": v,
      "Δ %": (delta &gt;= 0 ? "+" : "") + delta.toFixed(1) + "%"
    };
  }),
  {width: {Parameter: 320, "Canonical (v3)": 130, "Your value": 130, "Δ %": 80}}
)

Export / reset


Code
exportCSV = {
  const header = "Name,Expression,Notes\n";
  const note = (k) =&gt; canonical[k]?.notes ?? "User-edited via Parameter Playground";
  const rows = editedKeys.map(([k, v]) =&gt; `${k},${v},${note(k)}`).join("\n");
  const timestamp = new Date().toISOString().split(".")[0];
  return header
    + `# Scenario exported from Parameter Playground at ${timestamp},,\n`
    + `# Canonical baseline: amua_import_parameters_v3.csv,,\n`
    + rows + "\n";
}

downloadLink = {
  const blob = new Blob([exportCSV], {type: "text/csv"});
  const url = URL.createObjectURL(blob);
  return html`&lt;a href="${url}" download="d2p_scenario_${new Date().toISOString().split("T")[0]}.csv"
                 style="display:inline-block;padding:10px 18px;background:#04a;color:white;
                        text-decoration:none;border-radius:4px;font-weight:bold;margin:8px 4px;"&gt;
    ⬇ Download my scenario CSV
  &lt;/a&gt;`;
}

resetButton = html`&lt;button onclick="window.location.reload()"
  style="display:inline-block;padding:10px 18px;background:#666;color:white;
         border:none;border-radius:4px;font-weight:bold;cursor:pointer;margin:8px 4px;"&gt;
